sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        // Only run on insert or when dates/leave type change
        if (!current.isNewRecord() &&
            !current.start_date.changes() &&
            !current.end_date.changes() &&
            !current.leave_type.changes()) {
            return;
        }

        gs.info("[Enforce Leave] Starting validation for record: " + (current.number || "new record"));

        // Check for overlapping leave requests
        var hasOverlap = checkForOverlappingRequests(current);
        if (hasOverlap) {
            gs.addErrorMessage('This leave request overlaps with your existing request. Please choose different dates.');
            current.setAbortAction(true);
            return;
        }

        // Continue with leave balance validation
        validateLeaveBalance(current);

    } catch (e) {
        gs.error("[Enforce Leave] Error: " + e);
    }

    // Function to check for overlapping leave requests
    function checkForOverlappingRequests(leaveRequest) {
        // Skip if no dates
        if (leaveRequest.start_date.nil() || leaveRequest.end_date.nil()) {
            return false;
        }

        var overlapGR = new GlideRecordSecure('x_1800027_leve_sys_leave_request');

        // Don't compare with self (for updates)
        if (!leaveRequest.isNewRecord()) {
            overlapGR.addQuery('sys_id', '!=', leaveRequest.sys_id);
        }

        // Only check active requests (not cancelled or rejected)
        overlapGR.addQuery('status', 'NOT IN', 'cancelled,rejected');

        // Only check the current user's requests
        overlapGR.addQuery('requested_by', leaveRequest.requested_by);

        // Check date overlap - ignore time component
        var startDateStr = new GlideDateTime(leaveRequest.start_date).getDate();
        var endDateStr = new GlideDateTime(leaveRequest.end_date).getDate();

        overlapGR.addQuery('end_date', '>=', startDateStr);
        overlapGR.addQuery('start_date', '<=', endDateStr);

        overlapGR.query();

        if (overlapGR.next()) {
            gs.info("[Enforce Leave] Found overlapping request: " + overlapGR.number);
            return true;
        }

        return false;
    }

    // Function to validate leave balance
    function validateLeaveBalance(leaveRequest) {
        // Skip if no leave type or dates
        if (leaveRequest.leave_type.nil() ||
            leaveRequest.start_date.nil() ||
            leaveRequest.end_date.nil()) {
            return;
        }

        // Get leave balance
        var balanceGR = new GlideRecordSecure('x_1800027_leve_sys_leave_balance');
        balanceGR.addQuery('employee', leaveRequest.requested_by);
        balanceGR.addQuery('leave_type', leaveRequest.leave_type);

        // Get year from start date
        var startDate = new GlideDateTime(leaveRequest.start_date);
        var year = startDate.getYearLocalTime();

        balanceGR.addQuery('year', year);
        balanceGR.query();

        if (!balanceGR.next()) {
            gs.addErrorMessage('No leave balance record found for ' +
                leaveRequest.leave_type.getDisplayValue() +
                ' in ' + year + '. Request cannot be submitted.');
            leaveRequest.setAbortAction(true);
        } else {
            // Check if balance is sufficient
            var availableBalance = parseFloat(balanceGR.available_balance);
            var totalRequested = parseFloat(leaveRequest.duration);

            if (totalRequested > availableBalance) {
                gs.addErrorMessage('Insufficient leave balance. Available: ' +
                    availableBalance + ', Requested: ' +
                    totalRequested + '. Request cannot be submitted.');
                leaveRequest.setAbortAction(true);
            }
        }
    }
})(current, previous);
